-- Task 1 с графиками (DECISIONS 2026-11-27): у темы — график данными (writing.Chart), приложение рисует его
-- само, AI получает числа текстом. У проверки — копия графика: тема в банке может поменяться, разбор — нет.
-- Свои темы и данные, придуманные, в стиле Academic Task 1.
ALTER TABLE writing_prompts ADD COLUMN chart jsonb;
ALTER TABLE writing_checks ADD COLUMN chart jsonb;

INSERT INTO writing_prompts (task, text, chart) VALUES
('task1', 'The graph below shows the percentage of households with internet access in four countries between 2000 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"line","title":"Households with internet access, 2000–2020","unit":"% of households","x":["2000","2005","2010","2015","2020"],"series":[{"name":"South Korea","values":[49,75,96,99,99]},{"name":"Germany","values":[16,62,82,90,95]},{"name":"Brazil","values":[5,13,27,51,83]},{"name":"Uzbekistan","values":[1,4,15,41,76]}]}'),
('task1', 'The graph below shows the average monthly temperatures in Tashkent and London. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"line","title":"Average monthly temperature","unit":"°C","x":["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],"series":[{"name":"Tashkent","values":[2,4,10,16,21,27,29,27,21,14,8,3]},{"name":"London","values":[5,5,7,10,13,16,18,18,15,12,8,5]}]}'),
('task1', 'The graph below shows the number of international tourists visiting three cities from 2012 to 2022. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"line","title":"International visitors to three cities, 2012–2022","unit":"thousands","x":["2012","2014","2016","2018","2020","2022"],"series":[{"name":"Samarkand","values":[180,230,310,520,90,640]},{"name":"Bukhara","values":[150,170,220,380,60,450]},{"name":"Khiva","values":[60,75,95,160,25,210]}]}'),
('task1', 'The graph below shows the amount of electricity produced from three sources in one country between 1990 and 2030 (projected). Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"line","title":"Electricity production by source, 1990–2030 (2030 projected)","unit":"terawatt hours","x":["1990","2000","2010","2020","2030"],"series":[{"name":"Coal","values":[120,135,128,95,60]},{"name":"Natural gas","values":[40,70,110,130,125]},{"name":"Renewables","values":[10,12,25,60,140]}]}'),
('task1', 'The chart below shows the average number of hours per week that students in five age groups spent on different activities. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"bar","title":"Hours per week spent on activities, by age group","unit":"hours per week","x":["12–14","15–17","18–20","21–23","24–26"],"series":[{"name":"Studying","values":[18,24,22,17,10]},{"name":"Social media","values":[14,19,21,16,12]},{"name":"Sport","values":[8,6,5,4,4]}]}'),
('task1', 'The chart below shows the percentage of men and women in employment in six sectors in one country in 2023. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"bar","title":"Employment by sector and gender, 2023","unit":"% of employed men / women","x":["Agriculture","Manufacturing","Construction","Trade","Education","Health"],"series":[{"name":"Men","values":[24,18,17,15,6,4]},{"name":"Women","values":[21,12,2,19,18,14]}]}'),
('task1', 'The chart below shows the number of books borrowed from a city library in four categories in 2010 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"bar","title":"Books borrowed from a city library","unit":"thousands","x":["Fiction","Non-fiction","Children''s","Reference"],"series":[{"name":"2010","values":[85,40,55,20]},{"name":"2020","values":[52,46,78,6]}]}'),
('task1', 'The chart below shows the average water consumption per person per day in five countries. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"bar","title":"Water use per person per day","unit":"litres","x":["USA","Australia","Italy","China","India"],"series":[{"name":"Household","values":[380,340,250,90,45]},{"name":"Garden and outdoor","values":[160,150,40,15,10]}]}'),
('task1', 'The pie charts below show the main reasons why people moved to a large city in 1995 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"pie","title":"Reasons for moving to the city","unit":"%","pies":[{"name":"1995","parts":[{"name":"Work","value":46},{"name":"Education","value":18},{"name":"Family","value":24},{"name":"Housing","value":8},{"name":"Other","value":4}]},{"name":"2020","parts":[{"name":"Work","value":38},{"name":"Education","value":31},{"name":"Family","value":14},{"name":"Housing","value":11},{"name":"Other","value":6}]}]}'),
('task1', 'The pie charts below show how an average household in one country spent its income in 2000 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"pie","title":"Household spending","unit":"% of income","pies":[{"name":"2000","parts":[{"name":"Food","value":42},{"name":"Housing","value":20},{"name":"Transport","value":10},{"name":"Education","value":8},{"name":"Leisure","value":6},{"name":"Other","value":14}]},{"name":"2020","parts":[{"name":"Food","value":29},{"name":"Housing","value":24},{"name":"Transport","value":14},{"name":"Education","value":12},{"name":"Leisure","value":11},{"name":"Other","value":10}]}]}'),
('task1', 'The pie chart below shows the sources of waste produced by a city in one year. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"pie","title":"Sources of city waste in one year","unit":"%","pies":[{"name":"","parts":[{"name":"Households","value":38},{"name":"Construction","value":27},{"name":"Businesses","value":17},{"name":"Industry","value":13},{"name":"Other","value":5}]}]}'),
('task1', 'The table below shows the number of students enrolled in three types of higher education in one country in 2005, 2015 and 2025. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"table","title":"Students in higher education","unit":"thousands","columns":["Type","2005","2015","2025"],"rows":[["Universities","240","310","465"],["Technical colleges","180","165","140"],["Online programmes","5","45","210"]]}'),
('task1', 'The table below gives information about public transport in four cities. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"table","title":"Public transport in four cities","columns":["City","Metro lines","Daily passengers (millions)","Average fare (USD)","Opened"],"rows":[["London","11","4.0","3.80","1863"],["Moscow","15","6.5","0.70","1935"],["Tashkent","4","0.5","0.15","1977"],["Dubai","2","0.6","1.20","2009"]]}'),
('task1', 'The table below shows the percentage of people in different age groups who used a smartphone for four purposes in 2024. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"table","title":"Smartphone use by age group, 2024","unit":"% of each age group","columns":["Purpose","16–24","25–44","45–64","65+"],"rows":[["Messaging","98","95","88","71"],["Online banking","62","81","69","34"],["Watching video","94","78","52","28"],["Reading news","45","63","70","55"]]}'),
('task1', 'The table below shows the average price of four food items in a city market in 2015, 2020 and 2025. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.',
 '{"type":"table","title":"Average market prices","unit":"thousand som per kilogram","columns":["Item","2015","2020","2025"],"rows":[["Rice","6","11","17"],["Beef","32","58","95"],["Apples","5","9","10"],["Potatoes","2","4","7"]]}'),
('task1', 'The diagram below shows how bricks are manufactured for the building industry. Summarise the information by selecting and reporting the main features. Write at least 150 words.',
 '{"type":"process","title":"How bricks are made","steps":["Clay is dug from the ground by a large digger","The clay is placed on a metal grid and broken into small pieces","Sand and water are added and the mixture is shaped in moulds or cut by a wire cutter","The bricks are dried in a drying oven for 24–48 hours","They are heated in a kiln at 200–1300 °C","The bricks are cooled in a cooling chamber for 48–72 hours","The finished bricks are packaged and delivered to building sites"]}'),
('task1', 'The diagram below shows the stages in the production of cotton fabric. Summarise the information by selecting and reporting the main features. Write at least 150 words.',
 '{"type":"process","title":"From cotton plant to fabric","steps":["Cotton is planted in spring and watered for about five months","In autumn the cotton bolls are picked by machine or by hand","The cotton is cleaned to remove seeds, leaves and dirt","The fibres are pressed into large bales and sent to a mill","At the mill the fibres are combed and spun into thread","The thread is woven into fabric on large looms","The fabric is dyed, dried and rolled for sale"]}'),
('task1', 'The diagram below shows how rainwater is collected and treated for use in a home. Summarise the information by selecting and reporting the main features. Write at least 150 words.',
 '{"type":"process","title":"Rainwater collection for household use","steps":["Rain falls on the roof and runs into gutters","Leaves and dirt are removed by a filter at the top of the pipe","The water is stored in an underground tank","A pump sends the water to a second, finer filter","The water is treated with ultraviolet light to kill bacteria","Clean water is used for washing, the toilet and the garden"]}');
